        static readonly int[] CaveReturn = { CavePresentReturn, CaveMouseReturn, CaveFsModeReturn, CaveWin1Return, CaveWin2Return, CaveTogEndReturn, CaveDrawTextReturn, CaveDrawPostReturn, CaveHeldPumpReturn, CaveBrushReturn };

